export function getRuleById(id: string): LanguageRule | undefined {
  return LANGUAGE_RULES.find((rule) => rule.id === id);
}

export function rulesByCategory(): Record<string, LanguageRule[]> {
  const grouped: Record<string, LanguageRule[]> = {};
  for (const rule of LANGUAGE_RULES) {
    (grouped[rule.category] ??= []).push(rule);
  }
  return grouped;
}
